def generate(rng, n):
    if n < 2:
        n = 2
    nums = [rng.randint(-1000, 1000) for _ in range(n)]
    i = rng.randint(0, n - 2)
    j = rng.randint(i + 1, n - 1)
    if i == j:
        j = i + 1
    target = nums[i] + nums[j]
    return [nums, target]

def generate_worst(rng, n):
    if n < 2:
        n = 2
    nums = list(range(n))
    target = nums[-2] + nums[-1]
    return [nums, target]

